using Veriqa.Core.Configuration;

namespace Veriqa.Core.ChannelAdapter.UI;

/// <summary>
/// Registry of the key that overrides the built-in texts of the pages generated by the core — the
/// sign-in window, the hop page and the email pages — per tenant, per application and per
/// <c>ui_config</c> record (SPEC-012 §4.3, §10.6).
/// <para>
/// The key is declared HERE, next to <see cref="CorePageBrandingConfigKeys"/> and for the same reason:
/// its consumers are the pages of both the auth server and the email adapter, and the email adapter does
/// not reference the auth server.
/// </para>
/// <para>
/// One entry of the dictionary is addressed by the built-in Natural Key of the element it replaces, as
/// the identity dimension <see cref="TextDimensionName"/>. There is no core level: a text of the whole
/// installation is changed in the locale files of the host. For each text the highest level stating an
/// entry wins, and the entries of the other texts stated below it stay in force.
/// </para>
/// </summary>
public static class CorePageTextConfigKeys
{
    /// <summary>
    /// Catalog of the key declared in this class. It is filled by the initializer below and read
    /// afterwards by the registrar of the deployment.
    /// </summary>
    private static readonly ConfigKeyCatalog Declared = new();

    /// <summary>
    /// Name of the identity dimension of the key: the built-in Natural Key of the text an entry replaces.
    /// </summary>
    public const string TextDimensionName = "text";

    /// <summary>
    /// Name of the key, as the startup map and the snapshot report name it.
    /// </summary>
    internal const string KeyName = "AuthPage.Texts";

    /// <summary>
    /// Section of the dictionary inside the record of the tenant and inside the entry of a client.
    /// </summary>
    internal const string RecordSection = "AuthPage:Texts";

    /// <summary>
    /// Member of the dictionary inside a <c>ui_config</c> record, spelled the way that JSON contract
    /// spells its members.
    /// </summary>
    internal const string UiConfigSection = "texts";

    /// <summary>
    /// Segment the text an entry replaces takes in the address of every level.
    /// </summary>
    private const string TextSegment = ":{" + TextDimensionName + "}";

    /// <summary>
    /// Overrides of the built-in texts of the core pages (SPEC-012 §4.3). The value of a level for one text
    /// is either a replacement key or a map of ready texts by language (<see cref="CorePageTextOverride"/>).
    /// <para>
    /// The two forms are one member of the record, a text or a section, which an address cannot tell
    /// apart — hence the parse hook. The walk of a snapshot does not read through it, and the key says so:
    /// what the walk would check is not the domain of a value anyway but the text an entry is keyed by and
    /// the slots of the replacement against that text, which the owner's own snapshot catalogs report.
    /// </para>
    /// </summary>
    public static ConfigKey<CorePageTextOverride?> Texts { get; } = Declared
        .Of<CorePageTextOverride?>(KeyName)
        .Identity(TextDimensionName)
        .At(ConfigLevel.Tenant, RecordSection + TextSegment)
        .At(ConfigLevel.Application, RecordSection + TextSegment)
        .At(ConfigLevel.UiConfig, UiConfigSection + TextSegment)
        .Cached(ConfigCachePolicy.ExternalStore)
        .Parse(static (node, path, _) => CorePageTextOverride.Read(node, path))
        .NotWalked()
        .Declare();

    /// <summary>
    /// Declarations of the key — what the registrar of the deployment declares and binds.
    /// </summary>
    public static ConfigKeyCatalog Catalog => Declared;

    /// <summary>
    /// Levels the key lives at, each with the section of the dictionary inside its record.
    /// </summary>
    internal static IReadOnlyList<(ConfigLevel Level, string Section)> Levels { get; } =
    [
        (ConfigLevel.Tenant, RecordSection),
        (ConfigLevel.Application, RecordSection),
        (ConfigLevel.UiConfig, UiConfigSection)
    ];
}
